import { AnimatedIconFrame, type AnimatedIconProps } from "../icon-frame";
import "./clock.css";

export function AnimatedClockIcon(props: AnimatedIconProps) {
  return (
    <AnimatedIconFrame name="clock" {...props}>
      <circle cx="12" cy="12" r="10" />
      <path data-part="hand-long" d="M12 8v4" />
      <path data-part="hand-short" d="M12 12l2 2" />
    </AnimatedIconFrame>
  );
}

:is([data-icon-hover] .animated-icon, .animated-icon[data-icon-hover], .animated-icon[data-play]) {
  &[data-icon="clock"] {
    & [data-part^="hand"] {
      animation-name: icon-turn;
      animation-duration: var(--icon-duration-long);
      animation-timing-function: var(--ease-icon);
    }

    & [data-part="hand-long"] {
      --icon-turn: -360deg;
    }

    & [data-part="hand-short"] {
      --icon-turn: -90deg;
    }
  }
}
